root.classList.remove('community');root.innerHTML='<section class="screen">'+html+'</section>';loadCovers();if(view==='source'||view==='detail'){const region=root.querySelector('.scroll');if(region)region.scrollTop=scroll;}if(focus&&root.querySelector('#'+focus)){const el=document.getElementById(focus);el.focus();if(typeof selection==='number'&&el.setSelectionRange)try{el.setSelectionRange(selection,selection);}catch(_){}}if(!ready){ready=true;AtomApp.ready();}}
